  "tour.tasks.title": "இன்று என்ன செய்ய வேண்டும்",
  "tour.tasks.body": "உங்கள் பயிரின் தற்போதைய நிலைக்கான சிறு பட்டியல். முடித்ததும் குறியிடுங்கள் — இது பண்ணை ஆரோக்கிய மதிப்பெண்ணை உருவாக்கும்.",
  "tour.alerts.title": "முக்கியமான எச்சரிக்கைகள்",
  "tour.alerts.body": "வானிலை குறித்த எங்கள் மதிப்பீடு. சிவப்பு பொத்தான் உங்கள் மாவட்டத்தின் அதிகாரப்பூர்வ IMD எச்சரிக்கைகளைச் சரிபார்க்கும் — வானம் சரியில்லை எனத் தோன்றும்போது அழுத்துங்கள்.",
  "tour.assistant.title": "உங்கள் மொழியில் எதையும் கேளுங்கள்",
  "tour.assistant.body": "பயிர், திட்டம் அல்லது விலை பற்றி எழுதியோ பேசியோ கேளுங்கள். நீங்கள் தேர்ந்தெடுத்த மொழியில் பதில் வரும்.",
  "tour.sidebar.title": "மற்ற அனைத்தும் இங்கே",
  "tour.sidebar.body": "நோய் கண்டறிதல், மண் pH, சந்தை விலை, அரசு திட்டங்கள், அருகிலுள்ள கடைகள், இலவச நூலகம்.",
  "tour.done.title": "எல்லாம் தயார்",
  "tour.done.body": "இதுதான் அறிமுகம். அமைப்புகளிலிருந்து எப்போது வேண்டுமானாலும் மீண்டும் பார்க்கலாம்.",
  // Emergency alert check popup (Alerts card -> hazard modal)
