  "dataPrivacyModal.confirmBody": "இது உங்கள் சுயவிவரம், அனைத்து பண்ணைகள், பயிர் தரவு, செலவு பதிவுகள், அரட்டை வரலாறு மற்றும் நோய் ஸ்கேன் படங்களை நிரந்தரமாக நீக்கும். இந்த செயலை மாற்ற முடியாது.",
