  "dataPrivacyModal.deletionBody": "எங்கள் தக்கவைப்புக் கொள்கையின்படி உங்கள் தரவு 30 நாட்களுக்குள் மதிப்பாய்வு செய்யப்பட்டு நீக்கப்படும். மின்னஞ்சல் மூலம் உறுதிப்படுத்தலைப் பெறுவீர்கள்.",
