  "tour.stats.title": "మీ పొలం ఒక్క చూపులో",
  "tour.stats.body": "పొలాలు, మొత్తం విస్తీర్ణం, ప్రస్తుతం పండుతున్న పంటలు, ఈ సీజన్ లాభం. పని నమోదు చేస్తే ఇవి తమంతట తామే మారతాయి.",
  "tour.weather.title": "మీ పొలంలో వాతావరణం",
  "tour.weather.body": "మీ ప్రాంతపు ప్రస్తుత వాతావరణం, రాబోయే వారం. నేటి సలహా, పనులు దీని నుండే వస్తాయి.",
  "tour.tasks.title": "ఈరోజు ఏం చేయాలి",
  "tour.tasks.body": "మీ పంట ప్రస్తుత దశకు చిన్న జాబితా. పూర్తయ్యాక గుర్తు పెట్టండి — ఇది వ్యవసాయ ఆరోగ్య స్కోరును నిర్ణయిస్తుంది.",
  "tour.alerts.title": "ముఖ్యమైన హెచ్చరికలు",
  "tour.alerts.body": "వాతావరణంపై మా అంచనా. ఎరుపు బటన్ మీ జిల్లా అధికారిక IMD హెచ్చరికలను తనిఖీ చేస్తుంది — ఆకాశం సరిగా అనిపించనప్పుడు నొక్కండి.",
  "tour.assistant.title": "మీ భాషలో ఏదైనా అడగండి",
  "tour.assistant.body": "పంట, పథకం లేదా ధర గురించి రాసి లేదా మాట్లాడి అడగండి. మీరు ఎంచుకున్న భాషలో సమాధానం వస్తుంది.",
  "tour.sidebar.title": "మిగతావన్నీ ఇక్కడే",
  "tour.sidebar.body": "వ్యాధి గుర్తింపు, నేల pH, మార్కెట్ ధరలు, ప్రభుత్వ పథకాలు, సమీప దుకాణాలు, ఉచిత గ్రంథాలయం.",
  "tour.done.title": "అంతా సిద్ధం",
  "tour.done.body": "ఇదే పరిచయం. సెట్టింగ్స్ నుండి ఎప్పుడైనా మళ్లీ చూడవచ్చు.",
