  "tour.quickActions.title": "ഏറ്റവും കൂടുതൽ ചെയ്യുന്ന കാര്യങ്ങൾ",
  "tour.quickActions.body": "ചെലവ് ചേർക്കുക, രോഗമുള്ള ഇല സ്കാൻ ചെയ്യുക, മണ്ണിന്റെ pH വായിക്കുക, AI-യോട് ചോദിക്കുക, ഇന്നത്തെ വിപണി വില കാണുക — ഒറ്റ ടാപ്പിൽ.",
  "tour.stats.title": "നിങ്ങളുടെ കൃഷിയിടം ഒറ്റനോട്ടത്തിൽ",
  "tour.stats.body": "കൃഷിയിടങ്ങൾ, ആകെ വിസ്തീർണം, ഇപ്പോൾ വളരുന്ന വിളകൾ, ഈ സീസണിലെ ലാഭം. ജോലി രേഖപ്പെടുത്തുമ്പോൾ ഇവ സ്വയം പുതുക്കും.",
  "tour.weather.title": "നിങ്ങളുടെ സ്ഥലത്തെ കാലാവസ്ഥ",
  "tour.weather.body": "നിങ്ങളുടെ സ്ഥലത്തെ ഇപ്പോഴത്തെ കാലാവസ്ഥയും വരുന്ന ആഴ്ചയും. ഇന്നത്തെ ഉപദേശവും ജോലികളും ഇതിൽ നിന്നാണ്.",
  "tour.tasks.title": "ഇന്ന് എന്തു ചെയ്യണം",
  "tour.tasks.body": "നിങ്ങളുടെ വിളയുടെ ഇപ്പോഴത്തെ ഘട്ടത്തിനുള്ള ചെറിയ പട്ടിക. പൂർത്തിയാക്കിയാൽ അടയാളപ്പെടുത്തുക — ഇത് കൃഷി ആരോഗ്യ സ്കോർ നിർണയിക്കും.",
  "tour.alerts.title": "പ്രധാന മുന്നറിയിപ്പുകൾ",
  "tour.alerts.body": "കാലാവസ്ഥയെക്കുറിച്ചുള്ള ഞങ്ങളുടെ വിലയിരുത്തൽ. ചുവന്ന ബട്ടൺ നിങ്ങളുടെ ജില്ലയിലെ ഔദ്യോഗിക IMD മുന്നറിയിപ്പുകൾ പരിശോധിക്കും — ആകാശം ശരിയല്ലെന്നു തോന്നുമ്പോൾ അമർത്തുക.",
  "tour.assistant.title": "നിങ്ങളുടെ ഭാഷയിൽ എന്തും ചോദിക്കൂ",
  "tour.assistant.body": "വിള, പദ്ധതി അല്ലെങ്കിൽ വില സംബന്ധിച്ച് എഴുതിയോ പറഞ്ഞോ ചോദിക്കൂ. നിങ്ങൾ തിരഞ്ഞെടുത്ത ഭാഷയിൽ ഉത്തരം കിട്ടും.",
  "tour.sidebar.title": "ബാക്കിയെല്ലാം ഇവിടെ",
  "tour.sidebar.body": "രോഗനിർണയം, മണ്ണിന്റെ pH, വിപണി വില, സർക്കാർ പദ്ധതികൾ, അടുത്തുള്ള കടകൾ, സൗജന്യ ലൈബ്രറി.",
  "tour.done.title": "എല്ലാം തയ്യാർ",
  "tour.done.body": "ഇത്രയുമാണ് പരിചയം. ക്രമീകരണങ്ങളിൽ നിന്ന് എപ്പോൾ വേണമെങ്കിലും വീണ്ടും കാണാം.",
